SELECT 
FROM headphone


        AND brand = #{brand}


        AND model LIKE CONCAT('%', #{model}, '%')


        AND wireless = #{wireless}


        AND noise_cancelling = #{noiseCancelling}


        AND price >= #{minPrice}


        AND price <= #{maxPrice}


        AND price <= #{price}


ORDER BY price

mapper.update:
UPDATE headphone
model = #{model}, brand = #{brand}, driver_size = #{driverSize}, impedance = #{impedance}, sensitivity = #{sensitivity}, frequency_response = #{frequencyResponse}, price = #{price}, stock = #{stock}, wireless = #{wireless}, noise_cancelling = #{noiseCancelling}
WHERE id = #{id}

UPDATE headphone
SET stock = #{stock}
WHERE id = #{id}
